import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import App from './App';

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <BrowserRouter>
      <App />
    </BrowserRouter>
  </React.StrictMode>
);

import { Routes, Route, Navigate, NavLink } from 'react-router-dom';
import { Navbar, Nav, Container } from 'react-bootstrap';
import SubjectList from './pages/SubjectList';
import BulkAttendance from './pages/BulkAttendance';

export default function App() {
  return (
    <>
      <Navbar bg="primary" variant="dark">
        <Container>
          <Navbar.Brand>Attendance System</Navbar.Brand>
          <Nav className="me-auto">
            <Nav.Link as={NavLink} to="/subjects">Subjects</Nav.Link>
          </Nav>
        </Container>
      </Navbar>
      <Container className="my-4">
        <Routes>
          <Route path="/" element={<Navigate to="/subjects" replace />} />
          <Route path="/subjects" element={<SubjectList />} />
          <Route path="/subjects/:subjectId/attendance" element={<BulkAttendance />} />
        </Routes>
      </Container>
    </>
  );
}

// Today's date as "YYYY-MM-DD" in the LOCAL time zone (the value format of <input type="date">).
// Do NOT use new Date().toISOString().slice(0, 10): that is UTC, so in Vietnam (UTC+7)
// it still returns YESTERDAY between 00:00 and 06:59.
export function todayLocal() {
  const d = new Date();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${mm}-${dd}`;
}

import { useEffect, useMemo, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Row, Col, Card, Badge, Button, Form } from 'react-bootstrap';
import axios from 'axios';
import { API } from '../api';

export default function SubjectList() {
  const [subjects, setSubjects] = useState([]);
  const [keyword, setKeyword] = useState('');
  // ?status=ACTIVE is the single source of truth for the dropdown,
  // so opening /subjects?status=ACTIVE pre-selects ACTIVE on page load.
  const [searchParams, setSearchParams] = useSearchParams();
  const status = searchParams.get('status') || ''; // '' = All Status
  const navigate = useNavigate();

  useEffect(() => {
    axios.get(`${API}/subjects`).then((res) => setSubjects(res.data)); // fetched ONCE
  }, []);

  // Unique statuses extracted from the data — not hard-coded
  const statuses = useMemo(() => [...new Set(subjects.map((s) => s.status))], [subjects]);

  // Client-side filtering (no extra API call): name startsWith keyword (case-insensitive) AND status
  const kw = keyword.trim().toLowerCase();
  const filtered = subjects.filter(
    (s) => s.name.toLowerCase().startsWith(kw) && (status === '' || s.status === status)
  );

  const handleStatusChange = (e) => {
    const value = e.target.value;
    if (value) setSearchParams({ status: value });
    else setSearchParams({});
  };

  return (
    <>
      <h2 className="mb-0">Subject List</h2>
      <p className="text-muted">Browse and filter available subjects</p>

      <Card className="mb-3">
        <Card.Body>
          <Row className="g-2">
            <Col md={9}>
              <Form.Control id="search" placeholder="Search by name..." value={keyword} onChange={(e) => setKeyword(e.target.value)} />
            </Col>
            <Col md={3}>
              <Form.Select id="status-filter" value={status} onChange={handleStatusChange}>
                <option value="">All Status</option>
                {statuses.map((st) => (
                  <option key={st} value={st}>{st}</option>
                ))}
              </Form.Select>
            </Col>
          </Row>
        </Card.Body>
      </Card>

      <p className="text-muted showing-text">
        Showing <b>{filtered.length}</b> of {subjects.length} subjects
        {kw && <> matching <i>"{keyword.trim()}"</i></>}
        {status && <> with status <b>{status}</b></>}
      </p>

      <Row className="g-3">
        {filtered.map((s) => (
          <Col key={s.id} md={3}>
            <Card className="h-100 subject-card">
              <Card.Body>
                <Card.Title className="fw-bold subject-code">{s.code}</Card.Title>
                <Card.Text className="mb-1 subject-name">{s.name}</Card.Text>
                <Card.Text className="text-muted small">Credits: {s.credits}</Card.Text>
                <div className="d-flex justify-content-between align-items-center">
                  <Badge className="subject-status" bg={s.status === 'ACTIVE' ? 'success' : 'secondary'}>{s.status}</Badge>
                  <Button size="sm" className="view-attendance" onClick={() => navigate(`/subjects/${s.id}/attendance`)}>View Attendance</Button>
                </div>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </>
  );
}

import { useEffect, useState } from 'react';
import { Link, useParams, useSearchParams } from 'react-router-dom';
import { Card, Form, Table, Button, Alert, Row, Col } from 'react-bootstrap';
import axios from 'axios';
import { API } from '../api';
import { todayLocal } from '../dateUtils';

export default function BulkAttendance() {
  const { subjectId } = useParams();
  const [searchParams, setSearchParams] = useSearchParams();
  const classId = searchParams.get('classId') || ''; // ?classId=xxx

  const [subject, setSubject] = useState(null);
  const [classes, setClasses] = useState([]);
  const [students, setStudents] = useState([]);
  const [statusMap, setStatusMap] = useState({}); // studentId -> 'PRESENT' | 'ABSENT'
  const [date, setDate] = useState(todayLocal()); // defaults to today
  const [error, setError] = useState('');
  const [missingIds, setMissingIds] = useState([]);
  const [success, setSuccess] = useState('');

  useEffect(() => {
    axios.get(`${API}/subjects/${subjectId}`).then((res) => setSubject(res.data));
    axios.get(`${API}/classes?subjectId=${subjectId}`).then((res) => setClasses(res.data));
    axios.get(`${API}/students`).then((res) => setStudents(res.data));
  }, [subjectId]);

  // A different class => clear the radios and messages
  useEffect(() => {
    setStatusMap({});
    setError('');
    setMissingIds([]);
    setSuccess('');
  }, [classId]);

  const currentClass = classes.find((c) => c.id === classId);
  // Only students whose enrollment status is "enrolled" ("dropped" ones are NOT shown)
  const enrolled = currentClass
    ? currentClass.enrollments
        .filter((e) => e.status === 'enrolled')
        .map((e) => students.find((s) => s.id === e.studentId))
        .filter(Boolean)
    : [];

  const handleClassChange = (e) => {
    const value = e.target.value;
    if (value) setSearchParams({ classId: value });
    else setSearchParams({});
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setMissingIds([]);
    setSuccess('');

    if (!classId) return setError('Please select a class.');
    if (!date) return setError('Please select a date.');
    // Rule 1: no future date (YYYY-MM-DD strings compare correctly as text)
    if (date > todayLocal()) return setError('Date cannot be in the future.');
    // Rule 2: every student must have a status
    const missing = enrolled.filter((s) => !statusMap[s.id]);
    if (missing.length > 0) {
      setMissingIds(missing.map((s) => s.id));
      return setError(`Please select attendance status for all students (missing: ${missing.map((s) => s.studentCode).join(', ')}).`);
    }
    // Rule 3: attendance for this date must not exist yet in this class
    const { data: existing } = await axios.get(`${API}/attendances?classId=${classId}`);
    if (existing.some((a) => a.date.slice(0, 10) === date)) {
      return setError(`Attendance for ${date} already exists in this class.`);
    }
    // Success: POST one record per student
    const isoDate = `${date}T00:00:00.000Z`;
    for (const s of enrolled) {
      await axios.post(`${API}/attendances`, { studentId: s.id, classId, date: isoDate, status: statusMap[s.id] });
    }
    setSuccess(`Attendance recorded successfully for ${enrolled.length} student(s) on ${date}.`);
    setStatusMap({}); // reload the page state: radios reset, message kept
  };

  return (
    <Card>
      <Card.Body>
        <Card.Title>Record Attendance</Card.Title>
        {subject && <Card.Subtitle className="mb-3 text-muted subject-title">{subject.code} — {subject.name}</Card.Subtitle>}

        <Form onSubmit={handleSubmit}>
          <Row className="mb-3">
            <Col md={4}>
              <Form.Label>Class</Form.Label>
              <Form.Select id="class-select" value={classId} onChange={handleClassChange}>
                <option value="">-- Select class --</option>
                {classes.map((c) => (
                  <option key={c.id} value={c.id}>{c.className}</option>
                ))}
              </Form.Select>
            </Col>
            <Col md={4}>
              <Form.Label>Session Date</Form.Label>
              <Form.Control id="session-date" type="date" value={date} onChange={(e) => setDate(e.target.value)} />
            </Col>
          </Row>

          {currentClass && <p>Subject: <b>{subject?.name}</b> · Class: <b>{currentClass.className}</b></p>}
          {error && <Alert variant="danger" className="error-msg">{error}</Alert>}
          {success && <Alert variant="success" className="success-msg">{success}</Alert>}

          {currentClass && (
            <Table bordered hover id="student-table">
              <thead className="table-primary">
                <tr>
                  <th>No</th>
                  <th>Student Code</th>
                  <th>Full Name</th>
                  <th>Attendance Status</th>
                </tr>
              </thead>
              <tbody>
                {enrolled.map((s, i) => (
                  <tr key={s.id} id={`student-row-${s.id}`} className={`student-row ${missingIds.includes(s.id) ? 'table-warning' : ''}`}>
                    <td>{i + 1}</td>
                    <td className="student-code">{s.studentCode}</td>
                    <td>{s.fullName}</td>
                    <td>
                      {['PRESENT', 'ABSENT'].map((st) => (
                        <Form.Check
                          key={st}
                          inline
                          type="radio"
                          id={`att-${s.id}-${st}`}
                          name={`status-${s.id}`}
                          label={st}
                          checked={statusMap[s.id] === st}
                          onChange={() => setStatusMap({ ...statusMap, [s.id]: st })}
                        />
                      ))}
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
          )}

          <div className="d-flex justify-content-between">
            <Link to="/subjects">← Back to Subjects</Link>
            <Button id="record-attendance" type="submit" variant="success">Record Attendance</Button>
          </div>
        </Form>
      </Card.Body>
    </Card>
  );
}
